public class InnerDataAutomationProjectDocumentStandardExtractionFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction>
{

    internal InnerDataAutomationProjectDocumentBoundingBoxFactory BoundingBoxFactory { get; set; }

    internal InnerDataAutomationProjectDocumentExtractionGranularityFactory GranularityFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction Create()
    {
        var documentStandardExtractionResult = CreateDocumentStandardExtraction();
        factoryAction?.Invoke(documentStandardExtractionResult);

        return documentStandardExtractionResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction CreateDocumentStandardExtraction()
    {
        var documentStandardExtractionResult = new Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction();

        return documentStandardExtractionResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.DocumentStandardExtraction result)
    {
        base.CreateChildren(result);

        result.BoundingBox ??= BoundingBoxFactory?.Build();
        result.Granularity ??= GranularityFactory?.Build();
    }

} // End Of Class

